export function DispenseItemsTableCard({
  dispenses,
  edit,
  isFetching,
  orderClosed,
}: {
  dispenses: MedicationDispenseRead[];
  edit?: DispenseEditContext;
  isFetching?: boolean;
  /** Whether the parent dispense order is abandoned, entered-in-error, or completed. */
  orderClosed?: boolean;
}) {
  return (
    <div
      className={cn(
        "bg-gray-200 border border-gray-200 rounded-md overflow-hidden grid gap-px",
        edit
          ? "grid-cols-[1fr_1fr_auto_minmax(10rem,auto)_auto]"
          : "grid-cols-[1fr_1fr_auto_minmax(10rem,auto)]",
        isFetching && "animate-pulse opacity-20 pointer-events-none",
      )}
    >
      <DispenseItemsTable
        dispenses={dispenses}
        edit={edit}
        orderClosed={orderClosed}
      />
    </div>
  );
}

